encoder.module_tree:
StyleGAN2ResnetEncoder(
  (FromRGB): ConvLayer(
    (Conv): EqualConv2d(3, 32, 1, stride=1, padding=0)
    (Act): FusedLeakyReLU()
  )
  (DownToSpatialCode): Sequential(
    (ResBlockDownBy1): ResBlock(
      (conv1): ConvLayer(
        (RefPad): ReflectionPad2d((1, 1, 1, 1))
        (Conv): EqualConv2d(32, 32, 3, stride=1, padding=0)
        (Act): FusedLeakyReLU()
      )
      (conv2): ConvLayer(
        (Blur): Blur(
          (reflection_pad): ReflectionPad2d((2, 1, 2, 1))
        )
        (Conv): EqualConv2d(32, 64, 3, stride=2, padding=0)
        (Act): FusedLeakyReLU()
      )
      (skip): ConvLayer(
        (Blur): Blur()
        (Conv): EqualConv2d(32, 64, 1, stride=2, padding=0)
      )
    )
  )
  (ToSpatialCode): Sequential(
    (0): ConvLayer(
      (Conv): EqualConv2d(64, 64, 1, stride=1, padding=0)
      (Act): FusedLeakyReLU()
    )
    (1): ConvLayer(
      (Conv): EqualConv2d(64, 8, 1, stride=1, padding=0)
    )
  )
  (DownToGlobalCode): Sequential(
    (ConvLayerDownBy2): ConvLayer(
      (Blur): Blur()
      (Conv): EqualConv2d(64, 128, 3, stride=2, padding=0)
      (Act): FusedLeakyReLU()
    )
    (ConvLayerDownBy4): ConvLayer(
      (Blur): Blur()
      (Conv): EqualConv2d(128, 256, 3, stride=2, padding=0)
      (Act): FusedLeakyReLU()
    )
  )
  (ToGlobalCode): Sequential(
    (0): EqualLinear(256, 2048)
  )
)
